INSERT INTO `materiel` VALUES (2,'A7','A7sIII, ou Alpha 7.\r\nLa deuxième meilleure cam d\'Hyris après l\'Osmo bien sûr. Monture FE/E et très polyvalente même si on ne l\'utilise plus que pour des captations GdB avec un filtre ND64',1,1,'2023-11-01 12:57:36',1),(4,'Katherine','La table son d\'Hyris. Elle est indispensable en DT en Michelin pour mixer l\'audio du PC vid, des micros, et du PC son et renvoyer tout ça à Michelin et à la Couette.',1,3,'2023-11-01 13:27:30',1),(17,'GH5s','Un hybride polyvalent en monture MFT. Il est identique ou presque à son petit frère le Gh4.',1,1,'2023-11-01 23:53:54',1),(18,'Sigma 50mm','Un excellent objectif en montre EF',1,2,'2023-11-01 23:54:34',1),(19,'Bague d\'adaptation','Permet de monter les deux objectifs Sigma 20mm et 50mm ainsi que le Canon 24-70 sur les cameras Sony\r\nEF to FE',1,0,'2023-11-01 23:55:19',2),(21,'Sigma 20mm','Un excellent objectif en montre EF',1,2,'2023-11-01 23:56:04',1),(22,'Sony 85mm','Le seul objectif en monture FE de hyris, une pure tuerie qui coute un rein',1,2,'2023-11-01 23:56:54',1),(23,'Sigma 30mm','L\'objectif originel de Tess avec une mise au point en échelle log. Attention il est en monture E et non FE, il ne couvre donc pas tout le capteur de l\'A7',1,2,'2023-11-01 23:57:54',1),(34,'NXD+','Sony HXR-NX100\r\nFait partie des caméras les plus simples d\'utilisation et robustes d\'Hyris. Très utile pour faire des interviews ou en cam mobile.\r\n\r\nElle fait partie des trois NXD d\'Hyris, et est reconnaissable au fait qu\'il y a écrit 4K sur le côté du boîtier et qu\'elle possède un anneau pour fixer un micro à côté de son moniteur.\r\nCette NXD est la seule des trois qui puisse sortir un flux en SDI en plus de l\'HDMI, ce qui en fait une excellente cam mobile.\r\n\r\nLa contrepartie, c\'est que la NXD+ déteste les cartes SD et refusera d\'enregistrer n\'importe quoi, donc ne l\'utilisez pas pour un trounage ou vous allez vous sentir bien bête',1,1,'2023-11-13 12:56:27',1),(35,'NXD-','Fait partie des caméras les plus simples d\'utilisation et robustes d\'Hyris. Très utile pour faire des interviews, et généralement pas utilisée en DT.\r\n\r\nElle est reconnaissable au fait qu\'il n\'y a pas écrit 4K sur le côté du boîtier (ne croyez pas la photo), et qu\'elle a un cache intégré (à clapet).\r\nCette NXD ne sort qu\'en HDMI, donc prévoyez un convertisseur si besoin.',1,1,'2023-11-13 12:57:50',1),(36,'NNXD','Sony HXR-NX200\r\nFait partie des caméras les plus simples d\'utilisation et robustes d\'Hyris. Très utile pour faire des interviews ou en guise de cam fixe au DT.\r\n\r\nll s\'agit de la plus récente des trois NXD. Elle est reconnaissable au fait qu\'elle a un cache amovible (au lieu d\'un cache à clapet pour les deux autres)\r\nCette NXD ne sort qu\'en HDMI, donc prévoyez un convertisseur SDI/HDMI pour diffuser en DT.',1,1,'2023-11-13 12:58:16',1),(37,'FX-30','Sony FX30',1,1,'2023-11-13 14:27:14',1),(38,'Tess','Sony NEX FS-100\r\nTrès semblable aux NXD mais moins maniable, elle a toutefois une meilleure plage dynamique et fait des images globalement de meilleure qualité. A ne pas sous-estimer, même si vous avez été traumatisé par le combo Tess - grande glide...',1,1,'2023-11-13 14:29:19',1),(39,'DJI Osmo Pocket 2','Très portable, légère et stabilisée, l\'Osmo Pocket est la meilleure caméra en termes de rapport qualité d\'image/encombrement. Très adaptée pour les couvs sportives ou pour vlogger. LA meilleure caméra d\'hyris.',1,1,'2023-11-13 14:35:36',1),(40,'GH4','Paix à son âme \r\nWe\'ll remember you forever\r\n( Il a disparu de son armoire où il reposait en paix :(  )',0,1,'2023-11-13 14:38:28',1),(41,'GoPro Hero 7','',1,1,'2023-11-13 14:41:59',1),(42,'Ronin S2','RS2',1,4,'2023-11-13 14:42:39',1),(43,'Ronin SC2','RSC2',1,4,'2023-11-13 14:43:06',1),(44,'Ronin S3 Pro','RS3',1,4,'2023-11-13 14:43:22',1),(45,'Petite glide','',0,4,'2023-11-13 14:43:29',1),(46,'Grande glide','Glidecam HD-4000',1,4,'2023-11-13 14:43:35',1),(47,'Shoulder','Stab très adaptée aux interviews, et pour servir de cam mobile en DT. AIde à faire des plans en mouvement aussi',1,4,'2023-11-13 14:43:54',1),(48,'Grue','Proaim 10\' Wave 2 Plus. Très chiante à transporter et monter, elle n\'est jamais utilisée en tournage mais on la sort pour flex en soirée et afficher la tête des gens sur les écrans SBCS',1,4,'2023-11-13 14:44:10',1),(49,'Moniteur du Rush','',1,0,'2023-11-13 14:45:32',1),(50,'Color checker','Un pouvoir insoupçonné se cache derrière cet outil en apparence simpliste',1,0,'2023-11-13 14:45:36',1),(51,'GoPro Hero 9','',1,1,'2023-11-13 14:55:05',1),(52,'DJI Mavic 3 Classic','Le gros drone',1,1,'2023-11-13 14:55:24',1),(53,'DJI Mini SE','Le petit drone',1,1,'2023-11-13 14:56:31',1),(54,'Trépied light','Pour y mettre un panneau LED ou un micro',1,4,'2023-11-13 15:00:14',3),(55,'Trépied cam','Oubliez pas la plaquette',1,4,'2023-11-13 15:00:24',4),(56,'Scarlett 2i2','Notre carte d\'acquisition son, très adaptée pour enregistrer un top 50.',1,7,'2023-11-13 15:02:33',2),(57,'Couette','Elgato HD60X',1,3,'2023-11-13 15:04:26',1),(58,'Boîtier Daslight 4','C\'est le boîtier qui permet de contrôler les projecteurs colorés que ce soit en Rousseau ou en Michelin! C\'est l\'élément qui permet à Haziz d\'exister.',1,3,'2023-11-13 15:04:37',1),(59,'Platines Hercules','Les meilleures amies du PC son, utilisables avec DJuced.',0,3,'2023-11-13 15:05:36',1),(60,'Réa (Célestine)','Voilà une belle pièce, parmi le matériel le plus cher d\'Hyris. Permet de mixer en temps réel jusqu\'à 6 flux vidéo entrants',1,3,'2023-11-13 15:08:48',1),(61,'Launchpad S','Contrôleur MIDI compact, et souvent utilisé comme un deuxième clavier par Haziz.',1,3,'2023-11-13 15:12:09',1),(62,'Pad AKAI MPD 32','Ce pad est plus élaboré que le launchpad S grâce à ses faders, mais il est plus encombrant et peu utilisé en pratique.',1,3,'2023-11-13 15:13:50',1),(63,'AKAI MPK mini','Ce clavier MIDI a le mérite d\'exister. Un jour peut-être il sera utilisé par un Haziz motivé. Il peut aussi être utilisé pour faire du sound design et être utilisé par un VP Daniel motivé',1,3,'2023-11-13 15:15:08',1),(65,'Blimp','Notre immense moumoutte grise, très efficace pour bloquer les bruits de vent, mais ne la surestimez pas non plus...',1,7,'2023-11-13 15:28:22',1),(66,'Zoom','Enregistreur audio polyvalent.',1,7,'2023-11-13 15:30:05',3),(67,'Perche','Une perche télescopique pour aider en tournage. N\'oubliez pas de prendre une rotule avec.',1,7,'2023-11-13 15:32:43',4),(68,'Kit micro-cravate Rode','',1,7,'2023-11-13 15:34:00',1),(70,'Kit micros HF','Presque indispensable pour servir à la présentation des DT.',1,7,'2023-11-13 15:36:15',2),(71,'Réplique 1911','Pistolet d\'airsoft fonctionnant au gaz. Nécessite des précautions particulières pour le ranger.',1,6,'2023-11-13 15:38:37',1),(72,'Réplique Beretta 92','Pistolet d\'airsoft fonctionnant au gaz. Nécessite des précautions particulières pour le ranger.',1,6,'2023-11-13 15:38:53',1),(73,'Répéteur HDMI','',1,3,'2023-11-13 15:39:48',2),(74,'Convertisseur SDI/HDMI','',1,3,'2023-11-13 15:39:59',2),(75,'Kit d\'expansion Ronin','Nécessaire pour pouvoir mettre une caméra sur la grue',1,4,'2023-11-13 15:40:34',1),(76,'Poignées déportées Ronin','',1,4,'2023-11-13 15:40:39',1),(77,'Tenue d\'apiculteur','Ne posez pas de question.',1,6,'2023-11-13 15:50:01',2),(78,'Dédoubleur HDMI','',1,3,'2023-11-13 16:10:11',1),(79,'Stick RGB','Portable, puissant, coloré et facile d\'utilisation !',1,5,'2023-11-13 16:21:16',2),(80,'Panneau LED','Pour un éclairage blanc et fixe à température ajustable. Prenez un trépied light avec, et sécurisez-le si besoin.',1,5,'2023-11-13 16:32:33',3),(81,'Petite light','Ce petit bloc de LEDs chargeable avec des piles ou une batterie se fixe sur une NXD pour mieux faire des interviews.',1,5,'2023-11-13 16:34:35',1),(82,'Godox','Godox VL150',1,5,'2023-11-13 16:36:22',1),(83,'120d (Soleil)','Aputure C120d Mark II ',1,5,'2023-11-13 16:36:29',1),(84,'LS1c','Aputure LS1c',1,5,'2023-11-13 16:37:18',1),(85,'Tenture Hyris','Miteuse mais fidèle',1,6,'2023-11-13 16:38:57',1),(86,'Fond vert','Un grand rectangle vert en tissu qui fait bien l\'affaire si vous évitez les plis',1,0,'2023-11-13 16:40:04',1),(87,'Petit fond vert/bleu','Ce fond pliable (si vous êtes chauds) est recto-verso pour plus de choix',1,0,'2023-11-13 16:40:52',1),(88,'Réflecteur / diffuseur','Pour soigner la composition lumineuse de vos scènes !',1,5,'2023-11-13 16:41:18',4),(89,'Canon 24-70mm','Copie conforme de celui de Pics mais en presque meilleur état',1,2,'2023-11-13 16:44:04',1),(90,'Voigt 2','Voigt 10.5mm\r\nRobuste, fiable, mais prenez-en soin tout de même\r\nN\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:44:45',1),(91,'Voigt 0','Voigt 42.5mm\r\nN\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:44:57',1),(92,'Voigt 1','Voigt 25mm\r\nN\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:45:05',1),(93,'Fisheye 8mm','Samyang 8mm',1,2,'2023-11-13 16:46:32',1),(94,'Lumix 35-100mm','N\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:47:49',1),(95,'Lumix Pancake 20mm','Un vrai pancake capable de faire de la macro\r\nN\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:48:12',1),(96,'Lumix 12-35mm','N\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:48:21',1),(97,'Lumix 14-140mm','N\'oubliez pas le crop factor x2 du GH5s lorsque vous considérez la longueur focale',1,2,'2023-11-13 16:48:36',1),(98,'EVA-1','Panasonic AU-EVA1',1,1,'2023-11-13 22:58:25',1),(99,'Casque','',1,7,'2023-11-14 09:02:10',7),(100,'SSD 1','Un SSD T5 500Go',1,0,'2023-11-14 14:55:17',1),(101,'SSD 2','Un SSD T5 500 Go',1,0,'2023-11-14 14:55:41',1),(102,'SSD 3','Un SSD T5 500 Go',1,0,'2023-11-14 14:55:50',1),(103,'SSD 4','Un SSD T7 500 Go',1,0,'2023-11-14 14:56:01',1),(104,'SSD 5','Un SSD T7 500 Go',1,0,'2023-11-14 14:56:09',1),(105,'Micro canon','Micro directionnel très utile en tournage',1,7,'2023-11-15 21:05:30',3),(106,'Micro main','Pour faire des interviews',1,7,'2023-11-15 21:56:27',7),(107,'Zeiss 55mm','',1,2,'2023-11-19 21:08:40',1),(108,'Batterie NXD','utilisées pour alimenter les caméras éponymes, les sticks RGB, les moniteurs externes',1,8,'2023-11-20 10:46:42',13),(109,'V-Mount','Batteries très haute capacités qui servent à alimenter les panneaux LED et les Soleils ainsi que l\'EVA-1',1,8,'2023-11-20 10:48:00',6),(110,'C-Stand','Trépied très solide utilisés pour monter la 120d et la Godox',1,4,'2023-11-21 21:10:13',2),(112,'Kit micro-cravate Sennheiser','',1,7,'2023-11-27 11:19:00',2),(113,'Spicy Tenders','La meilleure poule, même avec un oeil en moins.',1,6,'2023-11-27 13:51:08',1),(114,'Nuggets','Encore meilleure poule que sa soeur',1,6,'2023-11-27 13:51:41',1),(115,'Les GPAs','On peut les nourrir avec du pain',1,6,'2023-11-27 14:11:42',1),(117,'Système son','Indispensable pour s’entraîner au PC son et pour les DT interlo les plus déjantés',1,0,'2023-12-06 18:53:01',1),(118,'Tête perche','À ne pas oublier si vous ne voulez pas que votre fiction soit muette',1,7,'2024-03-13 07:56:02',15),(119,'XLR Long','À ne pas oublier ',1,7,'2024-03-14 14:57:28',67),(120,'DJI Transmission','L\'argent le mieux investi d\'Hyris. Permet de retransmettre des flux vidéos à longue distance !',1,3,'2024-05-13 20:58:01',1),(121,'Sacs de sable','Pour stabiliser vos trépieds',1,0,'2024-06-03 11:24:47',4),(122,'Boitier Daslight 5','C\'est le boîtier qui permet de contrôler les projecteurs colorés que ce soit en Rousseau ou en Michelin! C\'est l\'élément qui permet à Haziz d\'exister.',1,3,'2024-12-03 12:18:57',1),(123,'DJI Mic 2','Le meilleur kit de micro d\'Hyris, facile et rapide à utiliser. Et je ne dis pas ça car je suis un amoureux de DJI',1,7,'2024-12-03 12:26:01',1),(124,'Platines FLX4','Les meilleures amies du PC son, utilisables avec Rekordbox ou Mixxx.',1,3,'2024-12-03 12:32:56',1),(125,'Enrouleur SDI','Enfin un bon moyen de ranger les sdi, though les SDI dessus sont kc',0,3,'2024-12-03 12:54:23',2),(126,'Panneau LED RGB','Amaran P60c, une light qui permet de gérer la couleur de la lumière ',1,5,'2024-12-03 13:04:55',1),(127,'Soleil RGB','Amaran 150c. Une spotlight où tu peux controler la couleur de la lumière',1,5,'2024-12-03 13:07:31',1),(128,'Poingnée cam','Permet de mieux tenir la caméra',1,4,'2024-12-03 13:14:49',2),(129,'DJI Avata 2','Le drone FPV, il se contrôle avec un RC motion 3, donc pas comme un vrai drone FPV. Permet de faire des plans très dynamiques et flottants. Désormais aussi controlable avec la manette FPV (mais cela nécessite un entraînement rigoureux)',1,1,'2025-04-06 10:29:41',1),(130,'A6700','Sony A6700, APS-C (crop x1.5), monture E, sorti en 2023',1,1,'2025-12-02 12:44:34',1),(131,'DJI Osmo Pocket 3','Très portable, légère et stabilisée, l\'Osmo Pocket est la meilleure caméra en termes de rapport qualité d\'image/encombrement. Très adaptée pour les couvs sportives ou pour vlogger. LA meilleure caméra d\'hyris. Grosse am&lioration de qualité par rapport à l\'osmo pocket 2',1,1,'2025-12-03 13:40:47',1),(132,'Tilt-shift','Objectif tilt TTartisan 50mm. Monture FE. Sans autofocus. Permet de donner un effet \"miniature\" à ce qu\'on filme.',1,2,'2025-12-03 13:45:02',1),(133,'Fisheye 7.5mm','Objectif fisteye 7.5mm TTartisan. E mount, sans autofocus. F2.0',1,2,'2025-12-03 14:10:27',1),(134,'Sony 35mm','Sony 35mm F1.8. Objectif FE, autofocus.',1,2,'2025-12-03 14:12:24',1),(135,'Tamron 35-150mm','Tamron 35-150mm F2-2.8. Objectif FE, avec autofocus.',1,2,'2025-12-03 14:14:10',1),(136,'Sony 16-50mm PZ','Sony 16-50mm PZ F3.5-5.6. E mount, auotofocus, zoom motorisé',1,2,'2025-12-03 14:17:14',1),(137,'Fond vert elgato','Fond vert depliable 180x200cm',1,0,'2025-12-03 14:19:18',1),(138,'Katherine (new gen)','L\'ancienne Katherine est partie en retraite à honolulu. Son poste a été repris par une Allen&Heath Qu5, mélangeur son tout récent numérique avec beaucoup trop de fonctionnalités.',1,3,'2025-12-03 14:36:25',1),(139,'Soleil RGB GVM','GVM SD300C. Soleil rgb de 300w, rien que ça.',1,5,'2025-12-03 14:39:12',1),(140,'Ronin S5','RS5',1,4,'2026-04-07 13:44:58',1),(141,'DJI Mic 3','Encore mieux que les Mic 2 ! (Les moumoutes sont adorables)',1,7,'2026-04-10 13:49:20',1),(142,'Sigma 16-28mm DG ','',1,2,'2026-05-13 14:44:01',1),(143,'FX-3','Sony FX3, la deuxième achetée de la gamme cinématographique de Sony. Elle supporte les montures E et FE avec son capteur full-frame',1,1,'2026-05-13 14:44:47',1),(144,'Manette FPV','Manette FPV pour l\'Avata 2. IL FAUT ABSOLUMENT DEMANDER L\'AUTORISATION POUR L\'UTILISER',1,6,'2026-05-28 14:38:49',1),(145,'Trépid à roulettes','Un trépied light... mais avec des roulettes pour pouvoir le déplacer plus facilement en tournage !',1,4,'2026-06-02 07:24:25',1),(146,'Stick RGB Neewer','Encore plus portable, encore plus puissant, encore plus coloré et encore plus facile d\'utilisation que les précédents !',1,5,'2026-06-02 07:48:00',2),(147,'Petit trépied light ','Venu avec les sticks RGB Neewer mais pas (?) compatible avec ptdr',1,4,'2026-06-02 07:50:16',2),(148,'Kit micro-cravate Rode Lavalier','',1,7,'2026-06-02 08:04:05',1),(149,'Les GDAs','Plus difficile que les GPAs sur la bouffe... ils sont vieux prenez en soin',1,0,'2026-06-04 12:30:56',1),(150,'Bellicule','Un GPA ou un GDA perdu...',1,0,'2026-06-06 17:23:06',1),(151,'Retropia 32mm','On sait pas vraiment pourquoi il est là mais il est là',1,2,'2026-06-06 17:24:58',1),(152,'DJI Transmission SDR','Aussi appelé bébé transmission par les intimes',1,3,'2026-06-06 17:58:54',1),(153,'DJI Osmo Action 6','Comme les GoPro mais version DJI',1,1,'2026-06-06 18:25:12',1),(154,'DJI Osmo 360','Une caméra 360°. Malheureusement, il faut un logiciel spécial pour l\'exploiter pleinement et il est lennnnnt sa mère',1,1,'2026-06-06 18:26:10',1),(155,'Micro Blue Baby Bottle SL','Un nouveau micro qui absorbe mieux les bruits de fond. Il sera donc meilleur pour faire ressortir les graves mais pas très pertinent pour des voix aigues (du moins je crois, demandez à Pharadox de la part de KiwiKool) ',1,7,'2026-06-06 19:14:55',1),(156,'Kit micros HF Shure','Un nouveau kit micros HF acheté parce que les anciens étaient pas pratiques du tout et fonctionnaient mal en Michelin',1,7,'2026-06-06 19:24:41',2),(157,'Batterie Sony','Les batteries utilisées pour alimenter les caméras Sony des séries A (prononcé Alpha) et FX.\r\nNotez que certaines sont officielles (les Sony) et d\'autres non (les Neewer). Lorsque vous utilisez la caméra sur une longue durée, il est recommandé de prendre une officielle',1,8,'2026-07-13 15:14:23',12),(158,'Batterie GH','Les batteries du GH5s',1,8,'2026-07-13 15:14:38',7),(159,'Lights de chantier','Existent pour aveugler les gens au camping du RAID ou pour faire des éclairages très puissants',1,5,'2026-07-13 15:25:59',2),(160,'Panneau LED Viltrox','Plus stylé et plus moderne pour faire des interviews que l\'ancien. N\'oubliez pas de récupérer un adaptateur pour le fixer à votre NXD',1,5,'2026-07-13 15:27:15',1),(161,'Gélatines','Pour donner des couleurs naturelles à vos lights blanches comme les pros du cinéma',1,5,'2026-07-29 19:52:00',1);
